sys.path.insert(0, '.')
from boltons.cacheutils import LRI, LRU, DEFAULT_MAX_SIZE
from boltons.cacheutils import PREV, NEXT, KEY, VALUE, _MISSING

def model_set(ref, order, max_size, k, v):
    # dict semantics: overwrite keeps position, new key appended at end
    existed = k in ref
    ref[k] = v
    if existed:
        order.remove(k)
    order.insert(0, k)
    while len(order) > max_size:
        ev = order.pop()          # ll-oldest
        del ref[ev]               # may be anywhere in dict order

def check(cache, ref, order, max_size, ctx):
    errs = []
    d = dict(cache)
    if d != ref:
        errs.append('%s: dict(cache)=%r != ref=%r' % (ctx, d, ref))
    vals = list(cache.values())
    expect_vals = [ref[k] for k in ref]
    if vals != expect_vals:
        errs.append('%s: values()=%r != %r' % (ctx, vals, expect_vals))
    if list(cache.items()) != list(ref.items()):
        errs.append('%s: items() mismatch: %r vs %r' % (ctx, list(cache.items()), list(ref.items())))
    if list(cache.keys()) != list(ref.keys()):
        errs.append('%s: keys() mismatch' % ctx)
    lk = cache._link_lookup
    if set(lk) != set(ref):
        errs.append('%s: link_lookup keys %r != dict keys %r' % (ctx, sorted(map(repr,lk)), sorted(map(repr,ref))))
    for k in ref:
        if k not in lk:
            continue
        if lk[k][VALUE] != ref[k]:
            errs.append('%s: link value for %r is %r, dict says %r' % (ctx, k, lk[k][VALUE], ref[k]))
        if lk[k][KEY] != k:
            errs.append('%s: link KEY %r != %r' % (ctx, lk[k][KEY], k))
    # walk ll
    anchor = cache._anchor
    walk = []
    link = anchor[NEXT]
    prev = anchor
    count = 0
    while link is not anchor:
        if link[PREV] is not prev:
            errs.append('%s: broken prev link' % ctx); break
        walk.append(link[KEY])
        prev = link
        link = link[NEXT]
        count += 1
        if count > 1000:
            errs.append('%s: ll loop too long' % ctx); break
    if anchor[PREV] is not prev:
        errs.append('%s: anchor PREV does not point at newest (inv 2)' % ctx)
    if walk != order:
        errs.append('%s: ll order %r != model order %r' % (ctx, walk, order))
    if anchor[KEY] is not _MISSING or anchor[VALUE] is not _MISSING:
        errs.append('%s: anchor not reset' % ctx)
    if len(ref) > max_size:
        errs.append('%s: len %d > max_size %d' % (ctx, len(ref), max_size))
    if len(cache) != len(ref):
        errs.append('%s: len(cache)=%d != len(ref)=%d' % (ctx, len(cache), len(ref)))
    return errs

def run(seed, cls, max_size, use_on_miss=False):
