from boltons.setutils import IndexedSet

random.seed(2024)
violations = []

def check_dead_invariants(s, tag, trace):
    items = s.item_list
    ded = s.dead_indices
    # every interval in range and pointing at _MISSING
    for ds, dt in ded:
        if not (0 <= ds < dt <= len(items)):
            violations.append((tag, 'interval out of range', list(ded), len(items), trace[-25:]))
            return False
        for i in range(ds, dt):
            if items[i] is not type(s)._MISSING if False else False:
                pass
    from boltons.setutils import _MISSING
    for ds, dt in ded:
        if 0 <= ds < dt <= len(items):
            for i in range(ds, dt):
                if items[i] is not _MISSING:
                    violations.append((tag, 'interval points at live slot', list(ded), i, trace[-25:]))
                    return False
    # every _MISSING covered by an interval
    covered = set()
    for ds, dt in ded:
        covered.update(range(ds, dt))
