from humanize import metric
random.seed(0)
SCALE = {'k':3,'M':6,'G':9,'T':12,'P':15,'E':18,'Z':21,'Y':24,'R':27,'Q':30,
         'm':-3,'μ':-6,'n':-9,'p':-12,'f':-15,'a':-18,'z':-21,'y':-24,'r':-27,'q':-30}
sup = str.maketrans("⁰¹²³⁴⁵⁶⁷⁸⁹⁻", "0123456789-")
def parse(s):
    m = re.match(r"^\s*(-?[\d.]+)\s*(?:x\s*10([⁻\d⁰¹²³⁴⁵⁶⁷⁸⁹]+))?\s*(\S*)$", s)
    if not m: return None, None
    base = float(m.group(1))
    if m.group(2): base *= 10 ** int(m.group(2).translate(sup))
    else:
        pre = m.group(3)[:-1]
        if pre: base *= 10 ** SCALE[pre]
    return base, m.group(0)
def sigdigits(s):
    num = s.split(" x ")[0].strip().lstrip("-")
    num = re.match(r"[\d.]+", num).group(0)
    d = num.replace(".","").lstrip("0") or "0"
    return len(d)

over, under, tol, exc = [], [], [], []
for i in range(200000):
    e = random.randint(-32, 34)
    # bias toward carry boundaries
    m_ = random.choice([random.uniform(1,1000), random.uniform(9.99,10), random.uniform(99.9,100),
                        random.uniform(999,1000), random.uniform(9.995,10), random.uniform(99.95,100),
                        random.uniform(999.5,1000), random.uniform(1,1000)])
    v = m_ * 10.0**e
    if not math.isfinite(v) or v == 0: continue
    if random.random() < 0.5: v = -v
    p = random.randint(3, 9)
    try:
        out = metric(v, "X", precision=p)
    except Exception as ex:
        exc.append((v,p,repr(ex))); continue
    if "x 10" in out:
        man = out.split(" x ")[0].lstrip("-")
        sd = len(man.replace(".","").lstrip("0") or "0")
        if sd > p: over.append((v,p,out,sd))
        continue
    got, _ = parse(out)
    sd = sigdigits(out)
    if sd > p: over.append((v,p,out,sd))
    elif sd < p: under.append((v,p,out,sd))
    ulp = 10 ** (math.floor(math.log10(abs(got))) - (sd-1)) if got else 0
    if abs(got - v) > 0.5*ulp*(1+1e-9): tol.append((v,p,out))
print("over:",len(over),"under:",len(under),"tol:",len(tol),"exc:",len(exc))
for b in over[:15]: print("OVER",b)
for b in under[:15]: print("UNDER",b)
for b in tol[:15]: print("TOL",b)
for b in exc[:15]: print("EXC",b)
