import math, random, re
from humanize import metric, scientific

def metric_old(value, unit="", precision=3):
    if not math.isfinite(value): return metric(value, unit, precision)
    exponent = math.floor(math.log10(abs(value))) if value != 0 else 0
    if exponent >= 33 or exponent < -30:
        return scientific(value, precision - 1) + unit
    old_bucket = exponent // 3 * 3
    value /= 10**old_bucket
    digits = int(max(0, precision - exponent % 3 - 1))
    if exponent < 30 and round(abs(value), digits) >= 1000:
        exponent += 3 - exponent % 3
        new_bucket = exponent // 3 * 3
        value /= 10 ** (new_bucket - old_bucket)
        digits = int(max(0, precision - exponent % 3 - 1))
    if exponent >= 3:
        ordinal_ = "kMGTPEZYRQ"[exponent // 3 - 1]
    elif exponent < 0:
        ordinal_ = "mμnpfazyrq"[(-exponent - 1) // 3]
    else:
        ordinal_ = ""
    value_ = format(value, f".{digits}f")
    if not (unit or ordinal_) or unit in ("°","′","″"):
        space = ""
    else:
        space = " "
    return f"{value_}{space}{ordinal_}{unit}"

SCALE = {'k':3,'M':6,'G':9,'T':12,'P':15,'E':18,'Z':21,'Y':24,'R':27,'Q':30,
         'm':-3,'μ':-6,'n':-9,'p':-12,'f':-15,'a':-18,'z':-21,'y':-24,'r':-27,'q':-30}
sup = str.maketrans("⁰¹²³⁴⁵⁶⁷⁸⁹⁻","0123456789-")
def parse(s):
    m = re.match(r"^\s*(-?[\d.]+)\s*(?:x\s*10([⁻\d⁰¹²³⁴⁵⁶⁷⁸⁹]+))?\s*(\S*)$", s)
    if not m: return None
    b = float(m.group(1))
    if m.group(2): b *= 10**int(m.group(2).translate(sup))
    else:
        p = m.group(3)[:-1]
        if p: b *= 10**SCALE[p]
    return b
def sig(s):
    n = s.split(" x ")[0].strip().lstrip("-")
    n = re.match(r"[\d.]+", n).group(0)
    return len(n.replace(".","").lstrip("0") or "0")

random.seed(1)
diffs_same_value = 0
diffs_value_changed = []
nondigit_change = []
for i in range(120000):
    e = random.randint(-31,33)
    v = random.uniform(1,1000)*10.0**e
    if random.random()<0.5: v=-v
    p = random.randint(3,9)
    a, b = metric_old(v,"X",p), metric(v,"X",p)
    if a==b: continue
    pa, pb = parse(a), parse(b)
    # value must agree (relative) - allow rounding-level differences
    rel = abs(pa-pb)/max(abs(pb),1e-300)
    if rel > 1e-9:
        diffs_value_changed.append((v,p,a,b))
    else:
        diffs_same_value += 1
        # new must not have MORE digits
        if sig(b) > sig(a): nondigit_change.append((v,p,a,b))
print("same-value fixes:", diffs_same_value)
print("value changed:", len(diffs_value_changed))
for x in diffs_value_changed[:20]: print("  ",x)
print("more digits:", len(nondigit_change))
for x in nondigit_change[:20]: print("  ",x)
