const SemVer = require('./work/repo/classes/semver')
const { compareIdentifiers } = require('./work/repo/internal/identifiers')

function upstreamPre (v, identifier, identifierBase) {
  const s = new SemVer(v)
  const base = Number(identifierBase) ? 1 : 0
  if (s.prerelease.length === 0) { s.prerelease = [base] } else {
    let i = s.prerelease.length
    while (--i >= 0) { if (typeof s.prerelease[i] === 'number') { s.prerelease[i]++; i = -2 } }
    if (i === -1) {
      if (identifier === s.prerelease.join('.') && identifierBase === false) throw new Error('invalid increment argument: identifier already exists')
      s.prerelease.push(base)
    }
  }
  if (identifier) {
    let prerelease = [identifier, base]
    if (identifierBase === false) prerelease = [identifier]
    const ids = identifier.split('.')
    let isPre = ids.length <= s.prerelease.length
    if (isPre) for (let i = 0; i < ids.length; i++) if (compareIdentifiers(s.prerelease[i], ids[i]) !== 0) { isPre = false; break }
    if (isPre) {
      const pb = s.prerelease[ids.length]
      if (isNaN(pb)) s.prerelease = prerelease
    } else s.prerelease = prerelease
  }
  return s.format()
}

