  let n, u
  try { n = new SemVer(v).inc('prerelease',id,b).version } catch(e){ n = 'THROW '+e.message }
  try { u = upstreamPre(v,id,b) } catch(e){ u = 'THROW '+e.message }
  if (n !== u) { diffs++; console.log(`v=${v} id=${id} base=${b}\n  new=${n}\n  upstream=${u}`) }
}
console.log('total diffs', diffs)
