const s = require('./work/repo')
const tuples = ['0.0.0','1.2.3','1.2.4','1.3.0','2.0.0','6.3.0','6.3.1','6.4.0','7.0.0','7.0.1','0.1.0']
const pres = ['', '-0', '-0.1', '-rc.1', '-rc.4', '-rc.5', '-rc.6', '-alpha', '-beta.2']
const versions = []
for (const t of tuples) for (const p of pres) versions.push(t + p)

const ranges = [
  '^6.3.0-rc.5', '^6.3.0-rc.4', '^6.3.0-rc.6', '^6.3.0', '^6.3.0-rc.4 <6.4.0-0',
  '^1.2.3-rc.1', '^1.2.3-rc.0', '^1.2.3', '1.2.3-rc.5', '1.2.3-rc.1',
  '^2.0.0-rc.1', '^2.0.0', '^7.0.0-rc.1', '^7.0.0', '~6.3.0-rc.1', '~6.3.0-rc.0',
  '>=6.3.0-rc.4', '>=6.3.0-rc.4 <7.0.0-0', '>6.3.0-rc.4 <7.0.0-0', '<7.0.0-0',
  '>=1.2.3-rc.0 <2.0.0-0', '1.x', '2.x', '^0.1.0-rc.1', '^0.1.0',
  '>=1.2.3-rc.0 <1.2.4-0', '^1.2.3-rc.5', '<=1.2.3-rc.1', '>1.2.3-rc.1 <2.0.0-0',
]

const check = (a, b) => {
  // returns 'bad-true' if subset says true but a version in a is not in b
  // returns 'suspect-false' if subset says false but all grid versions of a are in b
  const sub = s.subset(a, b)
  let witness = null
  for (const v of versions) {
    if (s.satisfies(v, a) && !s.satisfies(v, b)) { witness = v; break }
  }
  if (witness) return sub ? `BAD TRUE, witness ${witness}` : null // false is fine (true reason may exist outside grid)
  return sub ? null : 'SUSPECT FALSE'
}

for (const opt of [undefined, { includePrerelease: true }]) {
  console.log('== options', JSON.stringify(opt))
  const label = o => o ? ' (ip)' : ''
  for (const a of ranges) for (const b of ranges) {
    if (a === b) continue
    const r = (() => {
      const sub = s.subset(a, b, opt)
      let witness = null
      for (const v of versions) if (s.satisfies(v, a, opt) && !s.satisfies(v, b, opt)) { witness = v; break }
      if (witness) return sub ? `BAD TRUE witness ${witness}` : null
      return sub ? null : 'SUSPECT FALSE'
    })()
    if (r) console.log(`  ${JSON.stringify(a)} ⊂ ${JSON.stringify(b)}${label(opt)} => ${s.subset(a,b,opt)} : ${r}`)
  }
}
